import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class Main {
    public static void main(String[] args) throws Exception {
        String jsonBody = "{\"longUrl\":\"https://example.com\",\"utmSource\":\"app\"}";
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:8080/api/links"))
                .header("Authorization", "Bearer YOUR_API_KEY")
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(jsonBody))
                .build();

        HttpClient client = HttpClient.newHttpClient();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        System.out.println(response.body());
    }
}

export default function CreateLink() {
  const handleCreate = async () => {
    const res = await fetch('http://localhost:8080/api/links', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer YOUR_API_KEY',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        longUrl: 'https://example.com',
        utmCampaign: 'summer_sale'
      })
    });
    const data = await res.json();
    console.log(data);
  };

  return <button onClick={handleCreate}>Create Link</button>;
}
